-- Create "qa_project_outbox_manifests" table
CREATE TABLE "qa_project_outbox_manifests" ("id" uuid NOT NULL, "scenario" character varying NOT NULL, "nonce_hash" bytea NOT NULL, "control_capability_hash" bytea NOT NULL, "creation_generation" bigint NOT NULL, "organization_id" uuid NOT NULL, "owner_user_id" uuid NOT NULL, "session_id" uuid NOT NULL, "consumer_stream" character varying NOT NULL, "consumer_durable_name" character varying NOT NULL, "consumer_filter_subject" character varying NOT NULL, "consumer_config_fingerprint" bytea NOT NULL, "state" character varying NOT NULL DEFAULT 'creating', "project_id" uuid NULL, "created_by_id" uuid NULL, "cached_at" timestamptz NULL, "consumer_deleted_at" timestamptz NULL, "session_ended_at" timestamptz NULL, "owner_user_deleted_at" timestamptz NULL, "organization_deleted_at" timestamptz NULL, "cleanup_error_class" character varying NULL, "tombstoned_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "qa_project_outbox_manifests_hash_lengths" CHECK (COALESCE(octet_length(nonce_hash) = 32 AND octet_length(control_capability_hash) = 32 AND octet_length(consumer_config_fingerprint) = 32, FALSE)), CONSTRAINT "qa_project_outbox_manifests_uuid_authority_nonzero" CHECK (COALESCE(id <> '00000000-0000-0000-0000-000000000000'::uuid AND organization_id <> '00000000-0000-0000-0000-000000000000'::uuid AND owner_user_id <> '00000000-0000-0000-0000-000000000000'::uuid AND session_id <> '00000000-0000-0000-0000-000000000000'::uuid AND (project_id IS NULL OR project_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (created_by_id IS NULL OR created_by_id <> '00000000-0000-0000-0000-000000000000'::uuid), FALSE)), CONSTRAINT "qa_project_outbox_manifests_state_tombstone" CHECK (COALESCE(state IN ('creating','ready','project_registered','observer_disconnected','receipt_cached','quiescing','deleting','deleted','cleanup_failed') AND ((state = 'deleted') = (tombstoned_at IS NOT NULL)), FALSE)), CONSTRAINT "qa_project_outbox_manifests_cached_receipt_triple" CHECK (COALESCE((project_id IS NULL AND created_by_id IS NULL AND cached_at IS NULL) OR (project_id IS NOT NULL AND created_by_id IS NOT NULL AND cached_at IS NOT NULL), FALSE)));
