-- Canonicalize the state CHECK so PostgreSQL inspect/apply roundtrips retain one stable expression tree.
ALTER TABLE "qa_project_outbox_manifests" DROP CONSTRAINT "qa_project_outbox_manifests_state_tombstone", ADD CONSTRAINT "qa_project_outbox_manifests_state_tombstone" CHECK (COALESCE((((state)::text = ANY (ARRAY[('creating'::character varying)::text, ('ready'::character varying)::text, ('project_registered'::character varying)::text, ('observer_disconnected'::character varying)::text, ('receipt_cached'::character varying)::text, ('quiescing'::character varying)::text, ('deleting'::character varying)::text, ('deleted'::character varying)::text, ('cleanup_failed'::character varying)::text])) AND (((state)::text = 'deleted'::text) = (tombstoned_at IS NOT NULL))), false));
